<?php require '../includes/auth.php';require '../includes/header.php';$u=guard('employee');csrf_check();$id=$u['id'];
if(($_POST['_action']??'')==='apply'){if($_POST['end']<$_POST['start'])flash('End date is before start date','danger');else{db()->prepare("INSERT INTO leave_requests(employee_id,leave_type,start_date,end_date,reason) VALUES(?,?,?,?,?)")->execute([$id,$_POST['type'],$_POST['start'],$_POST['end'],trim($_POST['reason'])]);flash('Leave request submitted');}redirect('leave.php');}
$l=db()->prepare("SELECT * FROM leave_requests WHERE employee_id=? ORDER BY id DESC");$l->execute([$id]);
$c=db()->prepare("SELECT status,COUNT(*) n FROM attendance_records WHERE employee_id=? AND EXTRACT(MONTH FROM att_date)=EXTRACT(MONTH FROM CURRENT_DATE) AND EXTRACT(YEAR FROM att_date)=EXTRACT(YEAR FROM CURRENT_DATE) GROUP BY status");$c->execute([$id]);$sum=$c->fetchAll(PDO::FETCH_KEY_PAIR);
$h=db()->prepare("SELECT * FROM attendance_records WHERE employee_id=? AND att_date>=date_trunc('month',CURRENT_DATE) ORDER BY att_date DESC");$h->execute([$id]);page_head('Attendance & Leave',[],$u);?>
<div class="row g-3 mb-3"><?php foreach(ATT as $s){?><div class="col-6 col-md"><div class="card p-2 text-center"><div class="small text-muted"><?=e($s)?></div><b><?=(int)($sum[$s]??0)?></b></div></div><?php }?></div>
<form method="post" class="card p-3 mb-4 row g-2 flex-row"><?=csrf_field()?><input type="hidden" name="_action" value="apply"><div class="col-md-2"><select class="form-select" name="type"><option>Casual<option>Sick<option>Unpaid</select></div><div class="col-md-2"><input class="form-control" type="date" name="start" required></div><div class="col-md-2"><input class="form-control" type="date" name="end" required></div><div class="col-md-4"><input class="form-control" name="reason" placeholder="Reason" required></div><div class="col-md-2"><button class="btn btn-primary w-100">Apply</button></div></form>
<div class="row g-3"><div class="col-lg-7"><div class="card table-responsive"><table class="table mb-0"><tr><th>Type</th><th>Dates</th><th>Status</th><th>Admin comment</th></tr><?php foreach($l as $r){?><tr><td><?=e($r['leave_type'])?></td><td><?=e($r['start_date'].' → '.$r['end_date'])?></td><td><span class="badge text-bg-<?=['Approved'=>'success','Rejected'=>'danger'][$r['status']]??'warning'?>"><?=e($r['status'])?></span></td><td><?=e($r['admin_comment'])?></td></tr><?php }?></table></div></div>
<div class="col-lg-5"><div class="card table-responsive"><table class="table mb-0"><tr><th>Date</th><th>Status</th><th>In</th><th>Out</th></tr><?php foreach($h as $r)echo'<tr><td>'.e($r['att_date']).'</td><td>'.e($r['status']).'</td><td>'.e(substr((string)$r['check_in'],11,5)).'</td><td>'.e(substr((string)$r['check_out'],11,5)).'</td></tr>';?></table></div></div></div><?php page_foot();
